appearances.css:
.app{gap:3px;padding:4px 5px;border-radius:6px}
.app>.row{gap:3px 6px}
.app>.row select{font-size:10px;padding:3px 4px;min-height:26px;border-radius:3px;max-width:100px}
label.switch{font-size:10px;gap:3px;white-space:nowrap}
.screen{height:80px;border-radius:3px}
.controls{display:flex;flex-wrap:wrap;gap:2px 0;padding:4px 3px;background:var(--card-2);border:1px solid var(--line);border-radius:3px}
.controls label.control{flex:1 1 68px;min-width:0;padding:0;border:0;background:none;display:grid;justify-items:center;gap:0}
.controls .label{display:flex;flex-direction:column;align-items:center;gap:0;font-size:8px;letter-spacing:-.02em;line-height:1.15;text-align:center;max-width:100%;overflow-wrap:anywhere}
.controls output{font-size:8px;line-height:1.1;white-space:nowrap}
.controls .kn{order:-1;width:30px!important;height:30px!important;justify-self:center!important}
.controls .kn svg{width:100%;height:100%}
.app>.row button{font-size:10px;padding:4px 8px;min-height:26px;border-radius:3px}
.hint{display:none}
.status{font-size:9px;line-height:1.3}
p{font-size:9px;line-height:1.3;margin:0;color:var(--muted)}
details{padding:3px 5px;margin-bottom:3px;border-radius:3px}
summary{font-size:11px;margin-bottom:3px}
.app .route{grid-template-columns:minmax(64px,1fr) 62px minmax(60px,1fr) 38px;gap:4px;min-height:22px;font-size:10px}
.app .route select{font-size:9px;padding:1px 2px;min-height:22px;border-radius:3px}
.app .route output{font-size:9px}
.app .route input[type=range]{height:14px}
